    if s.startswith("-"):
        s = s[1:]
        negate = True
    else:
        negate = False

    if not s.startswith("$"):
        return Err("missing $")

    s = s[1:]
    parts = s.split(".")
    if len(parts) != 1 and len(parts) != 2:
        return Err("bad cents")

