type Instr = (
    Push(n: int)
    | Pop
    | Add
    | Sub
    | Mul
    | Dup
    | Swap
    | Jz(target: int)
    | Jmp(target: int)
    | Print
    | Halt
)

def stack_vm(prog: list[Instr]) -> Result[list[int], str]:
    stack: list[int] = []
    output: list[int] = []
    pc: int = 0
    steps: int = 0
    max_steps: int = 1000

    while pc < len(prog):
        steps += 1
        if steps > max_steps:
            return Err("step limit exceeded")

        match prog[pc]:
            case Push(n):
                stack.append(n)
            case Pop:
                if len(stack) == 0:
                    return Err(f"stack underflow at {pc}")
                stack.pop()
            case Add:
                if len(stack) < 2:
                    return Err(f"stack underflow at {pc}")
                stack.append(stack.pop() + stack.pop())
            case Sub:
                if len(stack) < 2:
                    return Err(f"stack underflow at {pc}")
                stack.append(-stack.pop() + stack.pop())
            case Mul:
                if len(stack) < 2:
                    return Err(f"stack underflow at {pc}")
                stack.append(stack.pop() * stack.pop())
            case Dup:
                if len(stack) == 0:
                    return Err(f"stack underflow at {pc}")
                stack.append(stack[-1])
            case Swap:
                if len(stack) < 2:
                    return Err(f"stack underflow at {pc}")
                stack[-1], stack[-2] = stack[-2], stack[-1]
            case Jz(target):
                if len(stack) == 0:
                    return Err(f"stack underflow at {pc}")
                if stack.pop() == 0:
                    pc = target
                    continue
            case Jmp(target):
                if target < 0 or target >= len(prog):
                    return Err(f"bad jump at {pc}")
                pc = target
                continue
            case Print:
                if len(stack) == 0:
                    return Err(f"stack underflow at {pc}")
                output.append(stack.pop())
            case Halt:
                break

        pc += 1

    return Ok(output)

