def build_order(jobs: list[Job]) -> Result[list[str], str]:
    job_map = {job.name: job for job in jobs}
    if len(job_map) != len(jobs):
        return Err(f"duplicate job: {next(name for name, count in Counter(job.name for job in jobs).items() if count > 1)}")
    for job in jobs:
        for dep in job.deps:
